/// Real CMSIS-style firmware against the STM32F103 flash controller: the
/// `FLASH` register window and the `0x0800_0000` main-flash gate. The first
/// program write is issued *before* the unlock and must be rejected; then the
/// KEYR handshake, a page erase, and a halfword program must land. The result
/// snapshot is `0xBEEF` only if both the gate and the program path worked.
const STM32_F103_FLASH_FIRMWARE: &str = r#"
#define STM32F10X_HD
#include "stm32f10x.h"

#define TARGET_ADDR 0x08000000u
#define RESULT_ADDR 0x20000000u

#define KEY1 0x45670123u
#define KEY2 0xCDEF89ABu

void reset(void) {
    /* 1. Still locked: CR.PG is ignored and the program write must not land. */
    FLASH->CR |= FLASH_CR_PG;
    *(volatile unsigned short *)TARGET_ADDR = 0xDEAD;
    unsigned locked = *(volatile unsigned short *)TARGET_ADDR;

    /* 2. Unlock through the KEYR key sequence. */
    FLASH->KEYR = KEY1;
    FLASH->KEYR = KEY2;

    /* 3. Erase the target page. */
    FLASH->CR |= FLASH_CR_PER;
    FLASH->AR = TARGET_ADDR;
    FLASH->CR |= FLASH_CR_STRT;
    while (FLASH->SR & FLASH_SR_BSY) { }

    /* 4. Program a halfword. */
    FLASH->CR |= FLASH_CR_PG;
    *(volatile unsigned short *)TARGET_ADDR = 0xBEEF;
    while (FLASH->SR & FLASH_SR_BSY) { }
    FLASH->SR = FLASH_SR_EOP;

    /* 5. Report: the locked write was rejected and the program landed. */
    unsigned programmed = *(volatile unsigned short *)TARGET_ADDR;
    *(volatile unsigned *)RESULT_ADDR = (locked == 0u) ? programmed : 0xFFFFFFFFu;
    __asm__ volatile("bkpt #0");
}
"#;

/// On the STM32F103 board, CMSIS firmware unlocks the `FLASH` controller,
/// erases a page, programs a halfword into `0x0800_0000`, and confirms that a
/// pre-unlock write was rejected by the write gate.
#[test]
fn stm32f103_flash_programming_is_gated_and_lands() {
    let includes = [
        "../packs/Keil.STM32F1xx_DFP/Device/Include",
        "../packs/STM32F4xx_CMSIS/CMSIS/Core/Include",
    ];
    let mut include_paths = Vec::new();
    for rel in includes {
        let include = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(rel);
        if !include.is_dir() {
            eprintln!(
                "skipping flash test: pack include dir {} not found",
                include.display()
            );
            return;
        }
        include_paths.push(
            include
                .to_str()
                .expect("pack include path is not UTF-8")
                .to_owned(),
        );
    }
    let include_refs: Vec<&str> = include_paths.iter().map(String::as_str).collect();
    let (code, symbols) =
        match build_firmware_with_includes(STM32_F103_FLASH_FIRMWARE, &include_refs) {
            Ok(image) => image,
            Err(why) => {
                eprintln!("skipping flash test: {why}");
                return;
            }
        };
    let entry = *symbols.get("reset").expect("no reset symbol");
    assert!(!code.is_empty(), "compiled .text must not be empty");

    let mut m = Machine::new(board::stm32f103());
    m.load_image(&load_flat(CODE_BASE, &code));
    {
        let mem = m.core.mem();
        mem.write_word(FLASH, INIT_SP).unwrap();
        mem.write_word(FLASH + 4, (CODE_BASE + entry) | 1).unwrap();
    }
    m.reset().expect("reset from vector table");
    let err = m.run(100_000);
    assert_eq!(err, Err(HaltCause::NonThumbTarget));
    assert_eq!(
        m.core.mem().read_word(0x2000_0000).unwrap(),
        0xBEEF,
        "the locked write was rejected and the program landed"
    );
}

/// Real CMSIS-style firmware against the STM32F1 DMA controller: a
/// memory-to-memory copy through `DMA1` channel 1, driven to completion by the
/// transfer-complete interrupt (IRQ 11, exception 27). The result snapshot is
/// `1` only if the 16-word copy landed, `CNDTR1` reads zero, `EN` self-cleared,
/// and the handler ran.
const STM32_F103_DMA_FIRMWARE: &str = r#"
#define STM32F10X_HD
#include "stm32f10x.h"

#define SRC_ADDR 0x20000100u
#define DST_ADDR 0x20000200u
#define DONE_ADDR 0x20000300u
#define RESULT_ADDR 0x20000304u
#define DONE_WORD (*(volatile unsigned *)DONE_ADDR)

void DMA1_Channel1_IRQHandler(void) {
    if (DMA1->ISR & DMA_ISR_TCIF1) {
        DONE_WORD = 1;
        DMA1->IFCR = DMA_IFCR_CTCIF1;
    }
}

void reset(void) {
    /* 1. Fill the source buffer with a 32-bit pattern. */
    volatile unsigned *src = (volatile unsigned *)SRC_ADDR;
    for (unsigned i = 0; i < 16; ++i) src[i] = 0xDEAD0000u | i;

    /* 2. Clear the destination. */
    volatile unsigned *dst = (volatile unsigned *)DST_ADDR;
    for (unsigned i = 0; i < 16; ++i) dst[i] = 0;

    /* 3. Arm the DMA1 channel-1 IRQ (IRQ 11, exception 27). */
    NVIC->ISER[0] = 1u << DMA1_Channel1_IRQn;

    /* 4. Memory-to-memory copy of 16 words, both sides incrementing. */
    DMA1_Channel1->CPAR = SRC_ADDR;
    DMA1_Channel1->CMAR = DST_ADDR;
    DMA1_Channel1->CNDTR = 16;
    DMA1_Channel1->CCR = DMA_CCR1_MEM2MEM | DMA_CCR1_PINC | DMA_CCR1_MINC |
                         DMA_CCR1_PSIZE_1 | DMA_CCR1_MSIZE_1 |
                         DMA_CCR1_TCIE | DMA_CCR1_EN;

    /* 5. Wait for the transfer-complete interrupt. */
    while (!DONE_WORD) { }

    /* 6. Verify the copy and the post-transfer register state. */
    unsigned ok = 1;
    for (unsigned i = 0; i < 16; ++i) {
        if (dst[i] != (0xDEAD0000u | i)) { ok = 0; break; }
        if (src[i] != (0xDEAD0000u | i)) { ok = 0; break; }
    }
    if (DMA1_Channel1->CNDTR != 0) ok = 0;
    if (DMA1_Channel1->CCR & DMA_CCR1_EN) ok = 0;

    *(volatile unsigned *)RESULT_ADDR = ok;
    __asm__ volatile("bkpt #0");
}
"#;

/// On the STM32F103 board, CMSIS firmware copies 16 words with `DMA1` channel
/// 1 in memory-to-memory mode, completes the transfer through the IRQ, and
/// verifies the result.
#[test]
fn stm32f103_dma_transfers_memory_to_memory() {
    let Some((code, symbols)) = build_f1_dma_firmware(STM32_F103_DMA_FIRMWARE) else {
        return; // skipped
    };
    let entry = *symbols.get("reset").expect("no reset symbol");
    let irq = *symbols
        .get("DMA1_Channel1_IRQHandler")
        .expect("no DMA1_Channel1_IRQHandler symbol");
    assert!(!code.is_empty(), "compiled .text must not be empty");

    let mut m = Machine::new(board::stm32f103());
    m.load_image(&load_flat(CODE_BASE, &code));
    {
        let mem = m.core.mem();
        mem.write_word(FLASH, INIT_SP).unwrap();
        mem.write_word(FLASH + 4, (CODE_BASE + entry) | 1).unwrap();
        // Vector 27 = DMA1_Channel1 IRQ 11 at FLASH + 27 * 4.
        mem.write_word(FLASH + 27 * 4, (CODE_BASE + irq) | 1)
            .unwrap();
    }
    m.reset().expect("reset from vector table");
    let err = m.run(100_000);
    assert_eq!(err, Err(HaltCause::NonThumbTarget));
    assert_eq!(
        m.core.mem().read_word(0x2000_0300).unwrap(),
        1,
        "the transfer-complete IRQ fired"
    );
    assert_eq!(
        m.core.mem().read_word(0x2000_0304).unwrap(),
        1,
        "the memory-to-memory copy was verified"
    );
}

/// Compile `firmware` against the STM32F1 device header, returning the flat
/// `.text` and symbol map, or `None` if the toolchain or pack is missing.
fn build_f1_dma_firmware(
    firmware: &str,
) -> Option<(Vec<u8>, std::collections::HashMap<String, u32>)> {
    let includes = [
        "../packs/Keil.STM32F1xx_DFP/Device/Include",
        "../packs/STM32F4xx_CMSIS/CMSIS/Core/Include",
    ];
    let mut include_paths = Vec::new();
    for rel in includes {
        let include = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(rel);
        if !include.is_dir() {
            eprintln!(
                "skipping dma test: pack include dir {} not found",
                include.display()
            );
            return None;
        }
        include_paths.push(
            include
                .to_str()
                .expect("pack include path is not UTF-8")
                .to_owned(),
        );
    }
    let include_refs: Vec<&str> = include_paths.iter().map(String::as_str).collect();
    match build_firmware_with_includes(firmware, &include_refs) {
        Ok(image) => Some(image),
        Err(why) => {
            eprintln!("skipping dma test: {why}");
            None
        }
    }
}

/// Real CMSIS-style firmware against the STM32F1 DMA request path: `USART1`
/// transmits a byte string over DMA1 channel 4 (memory→peripheral), driven to
/// completion by the channel-4 transfer-complete interrupt (IRQ 14, exception
/// 30). `RESULT` is `1` only if `CNDTR` read zero, `EN` self-cleared, and the
/// handler ran — and the host side asserts the transmitted bytes matched.
const STM32_F103_DMA_TX_FIRMWARE: &str = r#"
#define STM32F10X_HD
#include "stm32f10x.h"

#define TX_ADDR 0x20000100u
#define DONE_ADDR 0x20000300u
#define RESULT_ADDR 0x20000304u
#define DONE_WORD (*(volatile unsigned *)DONE_ADDR)

void DMA1_Channel4_IRQHandler(void) {
    if (DMA1->ISR & DMA_ISR_TCIF4) {
        DONE_WORD = 1;
        DMA1->IFCR = DMA_IFCR_CTCIF4;
    }
}

void reset(void) {
    /* 1. Fill the transmit buffer. */
    volatile unsigned char *tx = (volatile unsigned char *)TX_ADDR;
    const unsigned char msg[] = "dma ok!\n";
    unsigned len = 0;
    while (msg[len] != 0) { tx[len] = msg[len]; ++len; }

    /* 2. Enable clocks (gating is not enforced; kept for realism). */
    RCC->APB2ENR |= RCC_APB2ENR_IOPAEN | RCC_APB2ENR_USART1EN;

    /* 3. USART1 at 8 MHz HSI / 9600 baud, transmitter on. */
    USART1->BRR = 0x341;
    USART1->CR1 = USART_CR1_UE | USART_CR1_TE;

    /* 4. Arm the DMA1 channel-4 IRQ (IRQ 14, exception 30). */
    NVIC->ISER[0] = 1u << DMA1_Channel4_IRQn;

    /* 5. DMA1 channel 4: memory -> USART1 DR, byte units, memory increment.
          The USART1 TX request line feeds the channel every cycle. */
    DMA1_Channel4->CPAR = (unsigned)&USART1->DR;
    DMA1_Channel4->CMAR = TX_ADDR;
    DMA1_Channel4->CNDTR = len;
    DMA1_Channel4->CCR = DMA_CCR4_MINC | DMA_CCR4_TCIE | DMA_CCR4_EN;

    /* 6. Wait for the transfer-complete interrupt. */
    while (!DONE_WORD) { }

    /* 7. Verify the channel completed cleanly. */
    unsigned ok = 1;
    if (DMA1_Channel4->CNDTR != 0) ok = 0;
    if (DMA1_Channel4->CCR & DMA_CCR4_EN) ok = 0;
    *(volatile unsigned *)RESULT_ADDR = ok;
    __asm__ volatile("bkpt #0");
}
"#;

/// On the STM32F103 board, `USART1` TX drives `DMA1` channel 4 over the
/// peripheral-request line: the string reaches the host channel and the
/// channel-4 IRQ fires on completion.
#[test]
fn stm32f103_dma_transmits_usart1_via_peripheral_request() {
    let Some((code, symbols)) = build_f1_dma_firmware(STM32_F103_DMA_TX_FIRMWARE) else {
        return; // skipped
    };
    let entry = *symbols.get("reset").expect("no reset symbol");
    let irq = *symbols
        .get("DMA1_Channel4_IRQHandler")
        .expect("no DMA1_Channel4_IRQHandler symbol");
    assert!(!code.is_empty(), "compiled .text must not be empty");

    let mut m = Machine::new(board::stm32f103());
    m.load_image(&load_flat(CODE_BASE, &code));
    {
        let mem = m.core.mem();
        mem.write_word(FLASH, INIT_SP).unwrap();
        mem.write_word(FLASH + 4, (CODE_BASE + entry) | 1).unwrap();
        // Vector 30 = DMA1_Channel4 IRQ 14 at FLASH + 30 * 4.
        mem.write_word(FLASH + 30 * 4, (CODE_BASE + irq) | 1)
            .unwrap();
    }
    m.reset().expect("reset from vector table");
    let err = m.run(100_000);
    assert_eq!(err, Err(HaltCause::NonThumbTarget));
    let mut tx = Vec::new();
    for device in m.core.mem().devices_mut() {
        tx.extend(device.drain_output());
    }
    assert_eq!(tx, b"dma ok!\n", "the DMA-fed USART TX reached the host");
    assert_eq!(
        m.core.mem().read_word(0x2000_0304).unwrap(),
        1,
        "the peripheral-request transmit was verified"
    );
}

/// Real CMSIS-style firmware against the STM32F1 DMA request path in the
/// receive direction: `USART1` RX fills a buffer through DMA1 channel 5
/// (peripheral→memory), with the channel-5 transfer-complete interrupt (IRQ
/// 15, exception 31) signaling completion. The host injects four bytes one at
/// a time; `RESULT` is `1` only if they landed in order and the channel
/// completed cleanly.
const STM32_F103_DMA_RX_FIRMWARE: &str = r#"
#define STM32F10X_HD
#include "stm32f10x.h"

#define RX_ADDR 0x20000100u
#define DONE_ADDR 0x20000300u
#define RESULT_ADDR 0x20000304u
#define DONE_WORD (*(volatile unsigned *)DONE_ADDR)

void DMA1_Channel5_IRQHandler(void) {
    if (DMA1->ISR & DMA_ISR_TCIF5) {
        DONE_WORD = 1;
        DMA1->IFCR = DMA_IFCR_CTCIF5;
    }
}

void reset(void) {
    RCC->APB2ENR |= RCC_APB2ENR_IOPAEN | RCC_APB2ENR_USART1EN;

    USART1->BRR = 0x341;
    USART1->CR1 = USART_CR1_UE | USART_CR1_RE;

    NVIC->ISER[0] = 1u << DMA1_Channel5_IRQn;

    /* USART1 -> DMA1 channel 5, byte units, memory increment. */
    DMA1_Channel5->CPAR = (unsigned)&USART1->DR;
    DMA1_Channel5->CMAR = RX_ADDR;
    DMA1_Channel5->CNDTR = 4;
    DMA1_Channel5->CCR = DMA_CCR5_MINC | DMA_CCR5_TCIE | DMA_CCR5_EN;

    while (!DONE_WORD) { }

    volatile unsigned char *rx = (volatile unsigned char *)RX_ADDR;
    unsigned ok = (rx[0] == 'd') & (rx[1] == 'm') & (rx[2] == 'a') & (rx[3] == '\n');
    if (DMA1_Channel5->CNDTR != 0) ok = 0;
    if (DMA1_Channel5->CCR & DMA_CCR5_EN) ok = 0;
    *(volatile unsigned *)RESULT_ADDR = ok;
    __asm__ volatile("bkpt #0");
}
"#;

/// On the STM32F103 board, host-injected USART1 RX bytes are absorbed by `DMA1`
/// channel 5 over the peripheral-request line and verified by the firmware.
#[test]
fn stm32f103_dma_receives_usart1_via_peripheral_request() {
    let Some((code, symbols)) = build_f1_dma_firmware(STM32_F103_DMA_RX_FIRMWARE) else {
        return; // skipped
    };
    let entry = *symbols.get("reset").expect("no reset symbol");
    let irq = *symbols
        .get("DMA1_Channel5_IRQHandler")
        .expect("no DMA1_Channel5_IRQHandler symbol");
    assert!(!code.is_empty(), "compiled .text must not be empty");

    let mut m = Machine::new(board::stm32f103());
    m.load_image(&load_flat(CODE_BASE, &code));
    {
        let mem = m.core.mem();
        mem.write_word(FLASH, INIT_SP).unwrap();
        mem.write_word(FLASH + 4, (CODE_BASE + entry) | 1).unwrap();
        // Vector 31 = DMA1_Channel5 IRQ 15 at FLASH + 31 * 4.
        mem.write_word(FLASH + 31 * 4, (CODE_BASE + irq) | 1)
            .unwrap();
    }
    m.reset().expect("reset from vector table");
    // Inject the four bytes one at a time, giving the DMA a few cycles to
    // absorb each one before the next arrives on the wire. The final byte
    // completes the transfer and halts the firmware.
    for byte in b"dma\n" {
        for device in m.core.mem().devices_mut() {
            device.drive_inputs(u32::from(*byte));
        }
        if m.run(100) == Err(HaltCause::NonThumbTarget) {
            break;
        }
    }
    let err = m.run(100_000);
    assert_eq!(err, Err(HaltCause::NonThumbTarget));
    assert_eq!(
        m.core.mem().read_word(0x2000_0304).unwrap(),
        1,
        "the DMA-fed USART RX was verified"
    );
}

/// ARMv7-M firmware that enables `SHCSR.USGFAULTENA`, trips an undefined
/// instruction, and verifies the distinct `UsageFault` handler ran with the
/// `UNDEFINSTR` cause and no `FORCED` escalation.
///
/// The handler clears `USGFAULTENA` before its trailing `bkpt` so the debug
/// trap faults straight into (disabled) `HardFault`; with no `HardFault` vector
/// written the core halts with `NonThumbTarget`, leaving the `ENTRY`/`CAUSE`
/// snapshots intact.
const USAGE_FAULT_FIRMWARE: &str = r#"
#define SHCSR 0xE000ED24u
#define CFSR  0xE000ED28u
#define HFSR  0xE000ED2Cu
#define ENTRY 0x20000000u
#define CAUSE 0x20000004u
#define HFRS  0x20000008u

void UsageFault_Handler(void) {
    *(volatile unsigned *)ENTRY = 6;
    *(volatile unsigned *)CAUSE = *(volatile unsigned *)CFSR;
    *(volatile unsigned *)HFRS = *(volatile unsigned *)HFSR;
    *(volatile unsigned *)SHCSR &= ~0x40000u; /* stop re-faulting on the trap */
    __asm__ volatile("bkpt #0");              /* HardFault (disabled) -> halt */
}

void reset(void) {
    *(volatile unsigned *)SHCSR |= 0x40000u; /* USGFAULTENA */
    __asm__ volatile("udf #0");              /* -> distinct UsageFault */
}
"#;

/// On the STM32F103 board (ARMv7-M core), a distinct `UsageFault` exception is
/// taken for an undefined instruction when `USGFAULTENA` is set, and the
/// `UNDEFINSTR` cause is visible in `CFSR` without a `FORCED` escalation.
#[test]
fn usage_fault_is_a_distinct_exception_for_real_firmware() {
    let (code, symbols) = match build_firmware_v7m_with_includes(USAGE_FAULT_FIRMWARE, &[]) {
        Ok(image) => image,
        Err(why) => {
            eprintln!("skipping usage-fault test: {why}");
            return;
        }
    };
    let entry = *symbols.get("reset").expect("no reset symbol");
    let uf = *symbols
        .get("UsageFault_Handler")
        .expect("no UsageFault_Handler symbol");
    assert!(!code.is_empty(), "compiled .text must not be empty");

    let mut m = Machine::armv7m(board::stm32f103());
    m.load_image(&load_flat(CODE_BASE, &code));
    {
        let mem = m.core.mem();
        mem.write_word(FLASH, INIT_SP).unwrap();
        mem.write_word(FLASH + 4, (CODE_BASE + entry) | 1).unwrap();
        // UsageFault vector 6 at FLASH + 24; HardFault vector left unset so
        // the handler's `bkpt` escalates to HardFault -> vector 0 -> halt.
        mem.write_word(FLASH + 6 * 4, (CODE_BASE + uf) | 1).unwrap();
    }
    m.reset().expect("reset from vector table");
    let err = m.run(100_000);
    assert_eq!(err, Err(HaltCause::NonThumbTarget));
    assert_eq!(
        m.core.mem().read_word(0x2000_0000).unwrap(),
        6,
        "the UsageFault handler ran, not HardFault"
    );
    // UNDEFINSTR (UFSR bit 0 -> CFSR bit 16), no FORCED in HFSR.
    assert_eq!(m.core.mem().read_word(0x2000_0004).unwrap(), 0x0001_0000);
    assert_eq!(m.core.mem().read_word(0x2000_0008).unwrap(), 0);
}

/// ARMv7-M firmware that leaves `CPACR` at reset (FPU denied) and executes a
/// VFP instruction: the access is rejected with a `NOCP` `UsageFault`.
const NOCP_FIRMWARE: &str = r#"
#define SHCSR 0xE000ED24u
#define CFSR  0xE000ED28u
#define ENTRY 0x20000000u
#define CAUSE 0x20000004u

void UsageFault_Handler(void) {
    *(volatile unsigned *)ENTRY = 6;
    *(volatile unsigned *)CAUSE = *(volatile unsigned *)CFSR;
    *(volatile unsigned *)SHCSR &= ~0x40000u; /* stop re-faulting on the trap */
    __asm__ volatile("bkpt #0");              /* HardFault (disabled) -> halt */
}

void reset(void) {
    *(volatile unsigned *)SHCSR |= 0x40000u; /* USGFAULTENA */
    __asm__ volatile("vmov s0, r0");         /* CPACR denies: -> NOCP */
}
"#;

/// A VFP instruction with `CPACR` at zero (the reset state, denying FPU
